function renderFoods(){const q=($('#foodSearch').value||'').toLowerCase(),list=S.foods.map((f,i)=>({f,i})).filter(x=>(S.filter==='all'||x.f.cat===S.filter)&&x.f.name.toLowerCase().includes(q));$('#foods').innerHTML=list.map(x=>{const n=S.selected.get(x.i)||0,z=n?itemTotals(foodItemFromLib(x.f,n)):{kcal:0,p:0,c:0,f:0};return `<div class="foodItem ${n?'selected':''}"><div><b>${x.f.name}</b>${x.f.origin==='Meu alimento'?'<em>MEU ALIMENTO</em>':''}<small>${x.f.portion} • ${x.f.kcal} kcal • P${x.f.p} C${x.f.c} G${x.f.f}${x.f.approx?' • aprox.':''}</small></div><div class="qty gramsBuilder"><button onclick="foodQty(${x.i},-1)">−</button><b>${Math.round(n)} ${portionInfo(x.f.portion).unit}</b><button onclick="foodQty(${x.i},1)">+</button>${x.f._customId?`<button class="deleteFood" onclick="deleteCustomFood('${x.f._customId}')">×</button>`:''}</div></div>`}).join('')||'<p class="emptyFoods">Nenhum alimento encontrado.</p>';let k=0,p=0,c=0,f=0;for(const[i,n]of S.selected){const z=itemTotals(foodItemFromLib(S.foods[i],n));k+=z.kcal;p+=z.p;c+=z.c;f+=z.f}$('#foodCount').firstChild.textContent=S.selected.size+' itens • ';$('#builderTotals').textContent=`${Math.round(k)} kcal | P${Math.round(p)} C${Math.round(c)} G${Math.round(f)}`}
function foodQty(i,d){const f=S.foods[i],pi=portionInfo(f?.portion,f?.cat==='drink'?'ml':'g'),base=pi.amount,step=Math.max(pi.unit==='ml'?10:5,Math.round((base/2)/(pi.unit==='ml'?10:5))*(pi.unit==='ml'?10:5)),cur=S.selected.get(i)||0;let n;if(d>0&&cur<=0)n=base;else n=Math.max(0,cur+d*step);n?S.selected.set(i,n):S.selected.delete(i);renderFoods()}
async function saveMeal(){const name=$('#mealName').value.trim(),time=$('#mealTime').value;if(!name||!time||!S.selected.size)return toast('Informe nome, horário e alimentos.');const foodItems=[...S.selected].map(([i,n])=>foodItemFromLib(S.foods[i],n));let k=0,p=0,c=0,f=0;foodItems.forEach(x=>{const z=itemTotals(x);k+=z.kcal;p+=z.p;c+=z.c;f+=z.f});const key='custom_'+Date.now(),meal={key,name,time,target:Math.round(k),foodItems,foods:foodItems.map(foodLabel)};S.plan.meals.push(meal);await sb.from('meal_logs').upsert({user_id:session.user.id,log_date:S.currentDate,meal_key:key,meal_name:name,meal_time:time,foods:foodItems,kcal:k,protein_g:p,carbs_g:c,fat_g:f,completed:false},{onConflict:'user_id,log_date,meal_key'});closeFood();renderMeals();progress();toast('Refeição adicionada ✓')}
