function renderProfile(){if(!$('#profileBasics'))return;const p=S.p,show=v=>v===null||v===undefined||v===''?'Não informado':v;$('#profileBasics').innerHTML=`<p><b>Objetivo</b><span>${show(p.goal_text)}</span></p><p><b>Altura</b><span>${p.height_cm?show(p.height_cm)+' cm':'Não informado'}</span></p><p><b>Peso atual</b><span>${p.current_weight_kg?Number(p.current_weight_kg).toFixed(1)+' kg':'Não informado'}</span></p><p><b>Peso-alvo</b><span>${p.target_weight_kg?Number(p.target_weight_kg).toFixed(1)+' kg':'Não informado'}</span></p><p><b>Passos/dia</b><span>${p.steps_goal?Number(p.steps_goal).toLocaleString('pt-BR'):'Não informado'}</span></p><p><b>Sono</b><span>${p.sleep_hours?p.sleep_hours+' h':'Não informado'}</span></p>`;$('#hSteps').textContent=S.steps?`${S.steps.toLocaleString('pt-BR')} / ${(p.steps_goal||'—').toLocaleString?.('pt-BR')||'—'}`:(p.steps_goal?`— / ${Number(p.steps_goal).toLocaleString('pt-BR')}`:'Não informado');$('#bodyHistory').innerHTML=S.bodyHistory.length?S.bodyHistory.slice(0,12).map(x=>`<p><b>${x.log_date}</b><span>${x.weight_kg?x.weight_kg+' kg':''}${x.waist_cm?' • '+x.waist_cm+' cm cintura':''}${x.body_fat_pct?' • '+x.body_fat_pct+'% gordura':''}${x.steps?' • '+Number(x.steps).toLocaleString('pt-BR')+' passos':''}</span></p>`).join(''):'<p>Nenhum registro ainda.</p>';$('#loadHistory').innerHTML=S.loadHistory.length?S.loadHistory.slice(0,12).map(x=>`<p><b>${x.exercise_name}</b><span>${x.load_kg} kg • ${x.log_date}</span></p>`).join(''):'<p>Nenhuma carga registrada ainda.</p>'}
